#!/usr/bin/env bash
# Fixture for eval "setup-defaults": an indexed project that doc-superpowers
# setup has never run in: no record, no hooks, no Claude settings, no
# workflows, no .gitattributes.
. "$(dirname "$0")/../lib.sh"
fx_init "$0"

fx_write src/index.js <<'JS'
console.log('hello');
JS
fx_write docs/architecture/system-overview.md <<'MD'
<!-- Generated by doc-superpowers -->

# Architecture

A one-file CLI (`src/index.js`).
MD
fx_commit "init"
printf 'docs/architecture/system-overview.md:src/index.js:architecture\n' | dt build-index >/dev/null
fx_commit "docs: index"

fx_expect "no team record yet" test ! -e .claude/doc-superpowers/installed.json
fx_expect "no merge driver block yet" test ! -e .gitattributes
fx_expect "no git hook installed yet" test ! -e .git/hooks/pre-commit
fx_expect "no Claude settings yet" test ! -e .claude
fx_expect "no workflows yet" test ! -e .github
fx_expect "the index is committed" git ls-files --error-unmatch docs/.doc-index.json
